package org.apache.commons.math3.optimization.linear;

import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.apache.commons.math3.linear.Array2DRowRealMatrix;
import org.apache.commons.math3.linear.MatrixUtils;
import org.apache.commons.math3.linear.RealMatrix;
import org.apache.commons.math3.linear.RealVector;
import org.apache.commons.math3.optimization.GoalType;
import org.apache.commons.math3.optimization.PointValuePair;
import org.apache.commons.math3.util.Precision;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class SimplexTableau_dropPhase1Objective_TriageGen0Test {

    private SimplexTableau tableauUnderTest;
    private Method dropPhase1ObjectiveMethod;

    @Before
    public void setUp() throws Exception {
        // Since SimplexTableau is complex and the method is protected, 
        // we use a spy or a subclass to access protected members and manipulate state via reflection if necessary.
        tableauUnderTest = Mockito.spy(new SimplexTableau(new ArrayList<>(), null, true));

        dropPhase1ObjectiveMethod = SimplexTableau.class.getDeclaredMethod("dropPhase1Objective");
        dropPhase1ObjectiveMethod.setAccessible(true);
    }

    private void invokeDropPhase1Objective() throws Exception {
        dropPhase1ObjectiveMethod.invoke(tableauUnderTest);
    }

    /**
     * Helper to set private fields via reflection
     */
    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    /**
     * Helper to get private fields via reflection
     */
    private Object getField(Object target, String fieldName) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(target);
    }

    @Test
    public void testDropPhase1Objective_SingleObjectiveFunction() throws Exception {
        // If getNumObjectiveFunctions() == 1, the method should return immediately.
        doReturn(1).when(tableauUnderTest).getNumObjectiveFunctions();

        invokeDropPhase1Objective();

        // Verify no changes were made to the tableau (it remains the same instance or content)
        verify(tableauUnderTest, never()).getArtificialVariableOffset();
    }

    @Test
    public void testDropPhase1Objective_FullExecution() throws Exception {
        /*
         * Scenario to maximize coverage:
         * 1. getNumObjectiveFunctions() > 1
         * 2. Some positive cost non-artificial variables exist
         * 3. Some non-basic artificial variables exist
         * 4. Some basic artificial variables exist
         */

        // Mocking structural properties
        doReturn(2).when(tableauUnderTest).getNumObjectiveFunctions();
        doReturn(5).when(tableauUnderTest).getArtificialVariableOffset(); // Cols 5, 6... are artificial
        doReturn(2).when(tableauUnderTest).getNumArtificialVariables(); // 2 artificial variables
        doReturn(4).when(tableauUnderTest).getHeight(); // Rows 0, 1, 2, 3
        doReturn(8).when(tableauUnderTest).getWidth();  // Cols 0 to 7

        // Setup column labels (simulating internal state)
        List<Integer> labels = new ArrayList<>();
        for (int i = 0; i < 8; i++) labels.add(i);
        setField(tableauUnderTest, "columnLabels", labels);

        // Setup tableau matrix (4x8)
        // Row 0 is the objective row
        // Row 1-3 are constraint rows
        double[][] data = new double[4][8];
        data[0][0] = 10.0; // Should be dropped (index 0)
        data[0][5] = 5.0;  // Positive cost non-artificial (index 5) -> drop
        data[0][6] = -1.0; // Negative cost non-artificial (index 6) -> keep

        // Constraint rows (must be copied to new matrix)
        data[1][1] = 1.0; data[1][2] = 2.0; data[1][3] = 3.0; data[1][4] = 4.0; data[1][7] = 5.0;
        data[2][1] = 6.0; data[2][2] = 7.0; data[2][3] = 8.0; data[2][4] = 9.0; data[2][7] = 10.0;
        data[3][1] = 11.0; data[3][2] = 12.0; data[3][3] = 13.0; data[3][4] = 14.0; data[3][7] = 15.0;

        RealMatrix matrix = new Array2DRowRealMatrix(data);
        setField(tableauUnderTest, "tableau", matrix);
        setField(tableauUnderTest, "maxUlps", 1e-10);

        // Mocking getBasicRow for artificial variables
        // Artificial variables are at offset 5 and 6
        // col 5: basic (getBasicRow returns 1)
        // col 6: non-basic (getBasicRow returns null)
        doReturn(1).when(tableauUnderTest).getBasicRow(5);
        doReturn(null).when(tableauUnderTest).getBasicRow(6);

        // Execution
        invokeDropPhase1Objective();

        // Verification
        // columnsToDrop calculation:
        // 1. index 0 (always added)
        // 2. index 5 (entry 5.0 > 0)
        // 3. index 6 (getBasicRow is null)
        // Total dropped: {0, 5, 6}

        // New width should be 8 - 3 = 5
        // New height should be 4 - 1 = 3
        RealMatrix newMatrix = (RealMatrix) getField(tableauUnderTest, "tableau");
        assertEquals(3, newMatrix.getRowDimension());
        assertEquals(5, newMatrix.getColumnDimension());

        // Check if numArtificialVariables is reset
        assertEquals(0, (int) getField(tableauUnderTest, "numArtificialVariables"));

        // Check if labels were removed
        List<Integer> newLabels = (List<Integer>) getField(tableauUnderTest, "columnLabels");
        // Original labels 0-7. Dropped 0, 5, 6. Remaining: 1, 2, 3, 4, 7
        assertFalse(newLabels.contains(0));
        assertFalse(newLabels.contains(5));
        assertFalse(newLabels.contains(6));
        assertTrue(newLabels.contains(1));
        assertTrue(newLabels.contains(7));

        // Check content of new matrix (only rows 1, 2, 3 and non-dropped cols 1, 2, 3, 4, 7)
        // Row 1, Col 1 in original -> Row 0, Col 0 in new
        assertEquals(1.0, newMatrix.getEntry(0, 0), 1e-10);
        // Row 3, Col 7 in original -> Row 2, Col 4 in new
        assertEquals(15.0, newMatrix.getEntry(2, 4), 1e-10);
    }

    @Test
    public void testDropPhase1Objective_NoColumnsToDropExceptZero() throws Exception {
        // Scenario where only column 0 is dropped
        doReturn(2).when(tableauUnderTest).getNumObjectiveFunctions();
        doReturn(5).when(tableauUnderTest).getArtificialVariableOffset();
        doReturn(1).when(tableauUnderTest).getNumArtificialVariables(); 
        doReturn(2).when(tableauUnderTest).getHeight(); 
        doReturn(6).when(tableauUnderTest).getWidth();

        List<Integer> labels = new ArrayList<>();
        for (int i = 0; i < 6; i++) labels.add(i);
        setField(tableauUnderTest, "columnLabels", labels);

        double[][] data = new double[2][6];
        data[0][0] = 1.0;
        data[0][5] = -1.0; // non-artificial, negative cost, don't drop
        data[1][1] = 10.0; data[1][2] = 20.0; data[1][3] = 30.0; data[1][4] = 40.0; data[1][5] = 50.0;

        setField(tableauUnderTest, "tableau", new Array2DRowRealMatrix(data));
        setField(tableauUnderTest, "maxUlps", 1e-10);

        // Artificial variable at col 5 is basic
        doReturn(1).when(tableauUnderTest).getBasicRow(5);

        invokeDropPhase1Objective();

        RealMatrix newMatrix = (RealMatrix) getField(tableauUnderTest, "tableau");
        // Width: 6 - 1 (only col 0) = 5
        assertEquals(5, newMatrix.getColumnDimension());
        // Height: 2 - 1 = 1
        assertEquals(1, newMatrix.getRowDimension());

        List<Integer> newLabels = (List<Integer>) getField(tableauUnderTest, "columnLabels");
        assertEquals(5, newLabels.size());
        assertFalse(newLabels.contains(0));
    }
}
